1	"use client";
2	
3	import { createContext, useCallback, useContext, useEffect, useMemo, useRef, useState } from "react";
4	import { useSearchParams } from "next/navigation";
5	import { quoteOrder, type QuotedPrice } from "@/lib/nx/quote";
6	import { quoteGameOrder } from "@/lib/nx/quote-game";
7	import type { AddonOption, CartPrice, EmailPlanOption, GameFamilyOption, GameTier, HostingPlanOption, OsOption, PlanOption, TermOption } from "./order-types";
8	import type { Region } from "@/lib/nx/catalog";
9	import { DEPLOY_PARAM, type DeployIntent, type DeployService } from "@/lib/deploy-intent";
10	import { genDefaultVpsHostname } from "@/lib/hostname-shared";
11	import { checkHostnameAvailable } from "@/lib/actions-hostname-check";
12	
13	/* Order state for the deploy wizard.
14	 *
15	 * Ported from the design sandbox with ONE structural change, and it is the
16	 * important one: the sandbox derived every money figure here in the browser
17	 * (`dueToday`, `saved`, `walletApplied`, `cardDue`) from a fixture price table.
18	 * None of that survives. The server is asked what the selection costs, and this
19	 * context only holds the answer. A price the browser works out is a second
20	 * pricing formula, and the first time it disagrees with `orderQuote` a customer
21	 * is shown one number and charged another.
22	 *
23	 * Kept exactly as designed:
24	 *  - Choosing a service seeds a COMPLETE, working configuration, so the order is
25	 *    buyable without touching anything. Only free defaults are pre-set; nothing
26	 *    that adds to the total is ever ticked for you.
27	 *  - Once a service is picked nothing is gated — you can commit from anywhere.
28	 *  - This is deliberately NOT a <form>. On the live platform an unkeyed ternary
29	 *    once made Continue and Deploy the same DOM node and charged five customers
30	 *    four steps early. The commit action is its own button and nothing else can
31	 *    submit.
32	 */
33	
34	export type ServiceKey = "vps" | "game" | "hosting" | "email" | "domains";
35	
36	export type Order = {
37	  service: ServiceKey | null;
38	  planId: string | null;
39	  termMonths: number;
40	  region: string | null;
41	  osId: string | null;
42	  hostname: string;
43	  addons: string[];
44	  diskGb: number;
45	  couponCode: string;
46	  useWallet: boolean;
47	  launched: boolean;
48	
49	  /* ── game ── */
50	  /** Family the customer picked; the tier below is what they actually buy. */
51	  gameFamily: string | null;
52	  gamePlanId: string | null;
53	  gameVariant: string | null;
54	  /** Minecraft only — `<subdomain>.play.nxeon.cloud`. */
55	  subdomain: string;
56	  serverName: string;
57	  /**
58	   * Raw values for the selected game's `phase: "deploy"` config fields (e.g.
59	   * Valheim's SERVER_PASS) — validated + coerced server-side against the
60	   * family schema (lib/game-config.ts) in gameOrderQuote/placeGameOrder.
61	   * Found live 2026-09-15: this bucket never existed, so a required deploy
62	   * field (Valheim, CS2, Dragonwilds, Sunkenland, DST, Mordhau) always failed
63	   * checkout with no field ever shown to fix it — the wizard priced against
64	   * an empty config no matter what the customer did on the Server step.
65	   */
66	  gameConfig: Record<string, string>;
67	
68	  /* ── hosting & email ── */
69	  hostingPlanId: string | null;
70	  emailPlanId: string | null;
71	  /** The domain the account or mailboxes are bought FOR. */
72	  domain: string;
73	  /** Shared hosting: an nxeon subdomain instead of bringing your own name. */
74	  subdomainLabel: string;
75	
76	  /* ── domains ── */
77	  /** The exact name being registered, chosen from a search result. */
78	  domainName: string;
79	  domainPriceCents: number | null;
80	  years: number;
81	  /** Registrant contact. A domain is registered in a REAL person's name and
82	      these details go to the registry, so they are part of the order, not a
83	      profile setting to be filled in later. */
84	  contact: {
85	    firstName: string; lastName: string; address1: string; city: string;
86	    stateProvince: string; postalCode: string; country: string; phone: string; email: string;
87	  };
88	};
89	
90	const EMPTY: Order = {
91	  service: null, planId: null, termMonths: 1, region: null, osId: null,
92	  hostname: "", addons: [], diskGb: 0, couponCode: "",
93	  /* OFF by default. On means the balance silently pays and the customer never
94	     sees a card field — fine for a returning account with credit, confusing for
95	     everyone else. They opt IN to spending their balance. */
96	  useWallet: false, launched: false,
97	  gameFamily: null, gamePlanId: null, gameVariant: null, subdomain: "", serverName: "", gameConfig: {},
98	  domain: "", subdomainLabel: "", hostingPlanId: null, emailPlanId: null,
99	  domainName: "", domainPriceCents: null, years: 1,
100	  contact: { firstName: "", lastName: "", address1: "", city: "",
101	             stateProvince: "", postalCode: "", country: "", phone: "", email: "" },
102	};
103	
104	export type Section = { key: string; label: string; done: boolean; live: boolean };
105	
106	/** Status of a live "is this name available" round trip — shared shape with
107	 *  gameSubCheck/hostSubCheck (components/nx/DeployView.tsx). */
108	export type AvailabilityCheck = { status: "idle" | "checking" | "ok" | "bad"; reason?: string };
109	
110	export type Catalog = {
111	  plans: PlanOption[];
112	  /** Empty when the platform has no active game plans. */
113	  games: GameFamilyOption[];
114	  hosting: HostingPlanOption[];
115	  email: EmailPlanOption[];
116	  /* Plan x term effective monthly rates, computed server-side. Display only
117	     (the "$X/mo" labels) — rounded once already, so never re-multiply this
118	     back up by the term for a total; use the *TotalMatrix below instead. */
119	  hostingMatrix: Record<string, Record<number, number>>;
120	  /* Plan x term real charge totals (termPriceCents, unrounded until this one
121	     step) — the same number lib/actions-hosting.ts's hostingChargeCents
122	     charges. This is what checkout math reads. */
123	  hostingTotalMatrix: Record<string, Record<number, number>>;
124	  /* One month of THIS plan's rate, credited only if the signed-in customer
125	     still qualifies for first-month-free hosting — resolved server-side
126	     per-request (lib/promo-redemption.ts), since the flat matrix above has
127	     no per-customer awareness by design. 0 = no credit (promo off, or
128	     already claimed on this account/IP). */
129	  hostingFirstMonthFreeCents: Record<string, number>;
130	  emailMatrix: Record<string, Record<number, number>>;
131	  emailTotalMatrix: Record<string, Record<number, number>>;
132	  oses: OsOption[];
133	  terms: TermOption[];
134	  addons: AddonOption[];
135	  regions: Region[];
136	  diskPerGbCents: number;
137	  walletCents: number;
138	};
139	
140	type Ctx = {
141	  o: Order;
142	  set: <K extends keyof Order>(k: K, v: Order[K]) => void;
143	  chooseService: (k: ServiceKey) => void;
144	  chooseGame: (family: string) => void;
145	  game: GameFamilyOption | null;
146	  toggleAddon: (k: string) => void;
147	  reset: () => void;
148	  cat: Catalog;
149	  plan: PlanOption | null;
150	  /* server-priced */
151	  price: CartPrice;
152	  pricing: boolean;
153	  priceError: string | null;
154	  walletApplied: number;
155	  cardDue: number;
156	  sections: Section[];
157	  activeIdx: number;
158	  /** Live VPS-hostname availability — see the debounced effect below and
159	   *  lib/actions-hostname-check.ts. Idle for every non-VPS service. */
160	  hostCheck: AvailabilityCheck;
161	};
162	
163	/**
164	 * The full seed for a freshly-chosen service — same defaults `chooseService`
165	 * has always set (a complete, immediately-priceable order with only free
166	 * defaults ticked), pulled out as a pure function so `orderFromIntent` below
167	 * can start from the identical baseline before layering a marketing button's
168	 * specific selections on top. Takes the PREVIOUS order as `base` only so
169	 * fields the picker doesn't own (nothing today) would survive a re-seed —
170	 * `chooseService` and `orderFromIntent` both currently pass a full record in.
171	 */
172	function seedOrder(base: Order, cat: Catalog, k: ServiceKey): Order {
173	  const rec = cat.plans.find((p) => p.recommended) ?? cat.plans[0];
174	  return {
175	    ...base,
176	    service: k,
177	    planId: k === "vps" ? rec?.id ?? null : null,
178	    region: cat.regions[0]?.key ?? null,
179	    /* Must be a PLAIN_OS. Taking `oses[0]` picked whatever sorted first, and
180	       once the real catalogue landed that was Docker — an APPLICATION — so a
181	       fresh order defaulted to "operating system: Docker".
182	       Prefer the newest Ubuntu specifically — the most recognisable, most
183	       requested default — over whichever PLAIN_OS row happens to sort
184	       first alphabetically (AlmaLinux, before this). Falls back to the old
185	       "first PLAIN_OS" behavior if Ubuntu isn't in the catalogue at all. */
186	    osId: (
187	      cat.oses
188	        .filter((x) => x.category === "PLAIN_OS" && x.family === "ubuntu")
189	        .sort((a, b) => parseFloat(b.version || "0") - parseFloat(a.version || "0"))[0]
190	      ?? cat.oses.find((x) => x.category === "PLAIN_OS")
191	      ?? cat.oses[0]
192	    )?.id ?? null,
193	    termMonths: 1,
194	    /* A randomized "vps-xxxx" per order, never the same literal twice — was a
195	       hardcoded "web-01" until 2026-09-24, when production turned out to have
196	       7 unrelated customers all sharing that exact default (see
197	       lib/hostname.ts's doc comment for the resulting cross-customer
198	       data-exposure incident). Still only a STARTING point, not a uniqueness
199	       guarantee on its own: hostCheck below live-checks it (and whatever the
200	       customer edits it to) against the real DB as they type. */
201	    hostname: k === "vps" ? genDefaultVpsHostname() : "",
202	    serverName: k === "game" ? "My server" : "",
203	    addons: [],   // nothing that costs money is pre-selected
204	    diskGb: 0,
205	    /* A game order starts with NO family chosen — the picker is the next step,
206	       and pre-selecting one would put a product in the cart nobody asked for. */
207	    gameFamily: null, gamePlanId: null, gameVariant: null, subdomain: "",
208	    /* Hosting and email are bought against a DOMAIN, which only the customer
209	       can supply — there is no sensible default, so the field starts empty
210	       and the step is not "done" until they type one. */
211	    domain: "",
212	    subdomainLabel: "",
213	    /* Both seed their cheapest plan so the order is immediately priceable. */
214	    hostingPlanId: k === "hosting" ? (cat.hosting[0]?.id ?? null) : null,
215	    emailPlanId: k === "email" ? (cat.email[0]?.id ?? null) : null,
216	  };
217	}
218	
219	/** Reads a `DeployIntent` back off the URL, using the exact keys
220	 *  `lib/deploy-intent.ts`'s `deployHref` wrote — see that file for why each
221	 *  field has the query key it has. */
222	function parseIntent(sp: URLSearchParams): DeployIntent {
223	  const raw = (k: keyof DeployIntent) => sp.get(DEPLOY_PARAM[k]);
224	  const num = (k: keyof DeployIntent) => {
225	    const v = raw(k);
226	    if (!v) return undefined;
227	    const n = Number(v);
228	    return Number.isFinite(n) ? n : undefined;
229	  };
230	  const serviceRaw = raw("service");
231	  const service: DeployService | undefined =
232	    serviceRaw === "vps" || serviceRaw === "game" || serviceRaw === "hosting" || serviceRaw === "email"
233	      ? serviceRaw
234	      : undefined;
235	  const addonsRaw = raw("addons");
236	  return {
237	    service,
238	    planId: raw("planId") ?? undefined,
239	    termMonths: num("termMonths"),
240	    region: raw("region") ?? undefined,
241	    addons: addonsRaw ? addonsRaw.split(",").map((s) => s.trim()).filter(Boolean) : undefined,
242	    diskGb: num("diskGb"),
243	    gameFamily: raw("gameFamily") ?? undefined,
244	    gamePlanId: raw("gamePlanId") ?? undefined,
245	    gameVariant: raw("gameVariant") ?? undefined,
246	    players: num("players"),
247	    hostingPlanId: raw("hostingPlanId") ?? undefined,
248	    emailPlanId: raw("emailPlanId") ?? undefined,
249	    couponCode: raw("couponCode") ?? undefined,
250	  };
251	}
252	
253	/** The tier that best fits a desired headcount: the smallest slotted tier
254	 *  that still covers it, or — past the top of the ladder, or when the family
255	 *  has no slotted tiers at all — the single most expensive one, the closest
256	 *  real thing this family sells to "give me your biggest". Same judgment call
257	 *  GameLandingCombined's own player-count slider already makes, just applied
258	 *  against the LIVE catalogue instead of that page's illustrative fixture. */
259	function nearestTierBySlots(tiers: GameTier[], players: number): string | null {
260	  if (tiers.length === 0) return null;
261	  const slotted = tiers.filter((t): t is GameTier & { slots: number } => t.slots != null);
262	  const fits = slotted.filter((t) => t.slots >= players).sort((a, b) => a.slots - b.slots)[0];
263	  if (fits) return fits.id;
264	  const pool = slotted.length ? slotted : tiers;
265	  return [...pool].sort((a, b) => a.monthlyCents - b.monthlyCents).at(-1)?.id ?? null;
266	}
267	
268	/**
269	 * Materializes a `DeployIntent` into a real, catalogue-validated `Order` —
270	 * every id is checked against `cat` before it's used, so a stale or tampered
271	 * query string (an old link to a plan that's since been deactivated, say)
272	 * degrades to `seedOrder`'s normal defaults for whatever field didn't match,
273	 * never to a broken or half-filled order. Returns null when the URL carries
274	 * no recognised `product`, so the wizard opens on its ordinary empty first
275	 * step exactly as it always has.
276	 */
277	function orderFromIntent(cat: Catalog, intent: DeployIntent): Order | null {
278	  if (!intent.service) {
279	    // No specific service in the URL — but a coupon may still be attached
280	    // (a promo CTA that deliberately lands on the plain service picker
281	    // rather than defaulting into one product, e.g. lib/actions-promo-trial.ts's
282	    // ANY-service trial coupon — "works on any Game Server or Cloud VPS
283	    // plan" stops being true in practice if the button always drops the
284	    // customer into Game Servers specifically). Carry the coupon into the
285	    // ordinary empty first step instead of dropping it entirely.
286	    return intent.couponCode ? { ...EMPTY, couponCode: intent.couponCode } : null;
287	  }
288	  const o = seedOrder(EMPTY, cat, intent.service);
289	  // Applied regardless of which service branch runs below — a coupon covering
290	  // "any VPS or Game Server" (see lib/promo-trial.ts) isn't service-specific,
291	  // it just needs a real order to attach to.
292	  if (intent.couponCode) o.couponCode = intent.couponCode;
293	
294	  const term = intent.termMonths;
295	  if (term != null && cat.terms.some((t) => t.months === term)) o.termMonths = term;
296	
297	  if (intent.service === "vps") {
298	    if (intent.planId && cat.plans.some((p) => p.id === intent.planId)) o.planId = intent.planId;
299	    if (intent.region && cat.regions.some((r) => r.key === intent.region)) o.region = intent.region;
300	    if (intent.addons?.length) {
301	      const valid = new Set<string>(cat.addons.map((a) => a.key));
302	      const picked = intent.addons.filter((a) => valid.has(a));
303	      if (picked.length) o.addons = picked;
304	    }
305	    if (intent.diskGb != null && intent.diskGb >= 0) o.diskGb = Math.round(intent.diskGb);
306	  }
307	
308	  if (intent.service === "game") {
309	    const g = intent.gameFamily ? cat.games.find((x) => x.family === intent.gameFamily) : null;
310	    if (g) {
311	      o.gameFamily = g.family;
312	      const exact = intent.gamePlanId ? g.tiers.find((t) => t.id === intent.gamePlanId) : null;
313	      o.gamePlanId =
314	        exact?.id
315	        ?? (intent.players && intent.players > 0 ? nearestTierBySlots(g.tiers, intent.players) : null)
316	        ?? [...g.tiers].sort((a, b) => a.monthlyCents - b.monthlyCents)[0]?.id
317	        ?? null;
318	      o.gameVariant =
319	        intent.gameVariant && g.variants.some((v) => v.id === intent.gameVariant)
320	          ? intent.gameVariant
321	          : g.defaultVariant;
322	    }
323	  }
324	
325	  if (intent.service === "hosting" && intent.hostingPlanId && cat.hosting.some((h) => h.id === intent.hostingPlanId)) {
326	    o.hostingPlanId = intent.hostingPlanId;
327	  }
328	
329	  if (intent.service === "email" && intent.emailPlanId && cat.email.some((e) => e.id === intent.emailPlanId)) {
330	    o.emailPlanId = intent.emailPlanId;
331	  }
332	
333	  return o;
334	}
335	
336	const C = createContext<Ctx>(null as unknown as Ctx);
337	export const useOrder = () => useContext(C);
338	
339	export function OrderProvider({ cat, children }: { cat: Catalog; children: React.ReactNode }) {
340	  // Read once, on mount: a marketing "Deploy" button's selection, carried here
341	  // via `/dashboard/deploy?product=...` (see lib/deploy-intent.ts) — including
342	  // unchanged across a login/signup detour, since that's just the existing
343	  // `?next=` convention carrying this same query string through (see
344	  // lib/safe-next.ts, app/login/page.tsx, app/dashboard/layout.tsx).
345	  // `useSearchParams()` needs this component under a Suspense boundary, which
346	  // app/dashboard/deploy/page.tsx provides around <DeployView>.
347	  const searchParams = useSearchParams();
348	  const [o, setO] = useState<Order>(() => orderFromIntent(cat, parseIntent(searchParams)) ?? EMPTY);
349	  const [price, setPrice] = useState<CartPrice>(null);
350	  const [pricing, setPricing] = useState(false);
351	  const [priceError, setPriceError] = useState<string | null>(null);
352	  const [hostCheck, setHostCheck] = useState<AvailabilityCheck>({ status: "idle" });
353	
354	  const set = useCallback(<K extends keyof Order>(k: K, v: Order[K]) => {
355	    setO((p) => ({ ...p, [k]: v }));
356	  }, []);
357	
358	  const chooseService = useCallback((k: ServiceKey) => {
359	    setO((p) => seedOrder(p, cat, k));
360	  }, [cat]);
361	
362	  /* Choosing a family seeds its cheapest tier and its default loader, so the
363	     order is immediately priceable; the customer changes what they care about. */
364	  const chooseGame = useCallback((family: string) => {
365	    const g = cat.games.find((x) => x.family === family);
366	    if (!g) return;
367	    const cheapest = [...g.tiers].sort((a, b) => a.monthlyCents - b.monthlyCents)[0];
368	    setO((p) => ({
369	      ...p,
370	      gameFamily: family,
371	      gamePlanId: cheapest?.id ?? null,
372	      gameVariant: g.defaultVariant,
373	      subdomain: "",
374	      // A previous game's field values (e.g. Valheim's SERVER_PASS) must never
375	      // leak into a different family's config — keys rarely collide, but when
376	      // they do (two families both using SERVER_PASS) a stale value would
377	      // silently carry over instead of the customer setting their own.
378	      gameConfig: {},
379	    }));
380	  }, [cat]);
381	
382	  const toggleAddon = useCallback((k: string) => {
383	    setO((p) => ({
384	      ...p,
385	      addons: p.addons.includes(k) ? p.addons.filter((x) => x !== k) : [...p.addons, k],
386	    }));
387	  }, []);
388	
389	  const plan = useMemo(() => cat.plans.find((p) => p.id === o.planId) ?? null, [cat.plans, o.planId]);
390	  const game = useMemo(
391	    () => cat.games.find((g) => g.family === o.gameFamily) ?? null,
392	    [cat.games, o.gameFamily]
393	  );
394	
395	  /* ── live pricing ────────────────────────────────────────────────────────
396	     Debounced, and guarded against out-of-order replies: dragging the disk
397	     slider fires many quotes and they can come back in any order, so a stale
398	     one must never overwrite a newer one. Without the sequence check the cart
399	     can settle on the price of a selection the customer already moved past. */
400	  const seq = useRef(0);
401	  useEffect(() => {
402	    /* One effect, two products. Each asks ITS OWN server-side quote — the VPS
403	       one through `orderQuote`, the game one through `gameOrderQuote` — because
404	       the two price completely differently (a game tier is a flat term price;
405	       a VPS accrues add-ons, disk and a dedicated IP). Nothing here does
406	       arithmetic; it only chooses which server function to ask. */
407	    const vpsReady = o.service === "vps" && o.planId && o.osId;
408	    /* Minecraft cannot be quoted without its play subdomain: `quoteGameOrder`
409	       claims-checks the name, so asking before the customer has typed one comes
410	       back an error, and the wizard rendered that as a bare "—" total with the
411	       explanation buried in the cart. Wait for the field the family actually
412	       requires, and let the bar say what is missing instead. */
413	    const gameNeedsSubdomain = o.service === "game" && !!game?.needsSubdomain;
414	    const gameReady = o.service === "game" && o.gamePlanId
415	      && (!gameNeedsSubdomain || o.subdomain.trim().length > 2);
416	
417	    /* Hosting and email price from the server-built matrix the page handed down
418	       (termPriceCents — the same helper their charge paths use), so there is no
419	       round-trip to make and nothing for this effect to await. Still not derived
420	       HERE: the browser looks a value up, it does not compute one. */
421	    /* A domain is priced per YEAR by the registrar, already carrying our markup
422	       — there is no plan and no term ladder. The number came back from
423	       `searchDomains`; multiplying it by the years is the one arithmetic this
424	       file does, and it is the same multiplication `purchaseDomain` performs. */
425	    if (o.service === "domains") {
426	      if (o.domainPriceCents === null) { setPrice(null); setPriceError(null); return; }
427	      const total = o.domainPriceCents * o.years;
428	      setPricing(false);
429	      setPriceError(null);
430	      setPrice({
431	        totalCents: total, months: o.years * 12, regularPlanCents: total,
432	        promoName: "", promoCreditCents: 0,
433	        couponLabel: null, couponDiscountCents: 0, couponError: null,
434	        introRenewalMonthly: null,
435	        renewalTotalCents: total,
436	      });
437	      return;
438	    }
439	
440	    // Read the real term total directly — NOT the *Matrix per-month rate
441	    // multiplied back up. That rate is already rounded once (for its own
442	    // "$X/mo" display), so re-multiplying it by the term double-rounds and
443	    // drifts a cent or two from what the charge path actually bills (see
444	    // hostingTotalMatrix's comment in Catalog above).
445	    const total =
446	      o.service === "hosting" ? cat.hostingTotalMatrix[o.hostingPlanId ?? ""]?.[o.termMonths]
447	      : o.service === "email" ? cat.emailTotalMatrix[o.emailPlanId ?? ""]?.[o.termMonths]
448	      : undefined;
449	    if (total !== undefined) {
450	      // Hosting only, and only for a customer who still actually qualifies
451	      // (lib/promo-redemption.ts, resolved server-side per-request) — the
452	      // credit is 0 for email, and 0 for hosting once already claimed on
453	      // this account/IP, so `total` (the full price) is what shows either way.
454	      const promoCreditCents =
455	        o.service === "hosting" ? Math.min(total, cat.hostingFirstMonthFreeCents[o.hostingPlanId ?? ""] ?? 0) : 0;
456	      setPricing(false);
457	      setPriceError(null);
458	      setPrice({
459	        totalCents: total - promoCreditCents,
460	        months: o.termMonths,
461	        // The full, undiscounted term total — what the struck-through "was"
462	        // price (if the wizard shows one) should read, matching how the VPS
463	        // quote already reports `regularPlanCents` alongside its discounted total.
464	        regularPlanCents: total,
465	        promoName: promoCreditCents > 0 ? "First month free" : "",
466	        promoCreditCents,
467	        couponLabel: null, couponDiscountCents: 0, couponError: null,
468	        introRenewalMonthly: null,
469	        // The full undiscounted term total — first-month-free is a one-time
470	        // credit, never repeated at renewal, same reasoning as regularPlanCents.
471	        renewalTotalCents: total,
