16	/** Extract the real client IP from proxy headers (nginx sets X-Real-IP and the
17	 *  X-Forwarded-For chain; we trust the first hop). Returns null if unusable. */
18	export function clientIpFromHeaders(hdrs: Headers): string | null {
19	  const real = hdrs.get("x-real-ip")?.trim();
20	  if (real) return real;
21	  const fwd = hdrs.get("x-forwarded-for");
22	  if (fwd) {
