29	/** ISO-3166 alpha-2 country for an IP, or null. Private/loopback/unknown → null. */
30	export function countryFromIp(ip: string | null | undefined): string | null {
31	  if (!ip) return null;
32	  // Skip private/loopback ranges — geoip returns null anyway, but cheap to guard.
33	  if (
34	    ip === "127.0.0.1" ||
35	    ip === "::1" ||
36	    ip.startsWith("10.") ||
37	    ip.startsWith("192.168.") ||
38	    /^172\.(1[6-9]|2\d|3[01])\./.test(ip)
39	  ) {
40	    return null;
41	  }
42	  try {
43	    const hit = geoip.lookup(ip);
44	    const cc = hit?.country?.trim().toUpperCase();
45	    return cc && cc.length === 2 ? cc : null;
46	  } catch {
47	    return null;
48	  }
49	}
