/** Build the picker's region list from the nodes that actually exist.
 *
 * Sorted by region KEY, not by whatever order the `nodes` array arrived in.
 * The caller's `Node` query has no natural order of its own (Postgres makes
 * no ordering guarantee without an explicit `orderBy`), so building this Map
 * straight off it made the region list — and, worse, "region #0", the wizard's
 * SEEDED DEFAULT — reshuffle from one page load to the next. A customer could
 * land on a random datacentre with no region actually chosen. Sorting here
 * makes the list (and anything that reads `regions[0]`) deterministic
 * regardless of query order; `defaultRegionKey` below is the real "which one
 * should be picked FOR the customer" decision. */
export function regionsFrom(nodes: { id: string; region: string }[]): Region[] {
  const byRegion = new Map<string, string[]>();
  for (const n of nodes) {
    if (!COORDS[n.region]) continue; // no coordinates -> cannot be drawn, so not offered
    const list = byRegion.get(n.region) ?? [];
    list.push(n.id);
    byRegion.set(n.region, list);
  }
  return [...byRegion.entries()]
    .map(([code, nodeIds]) => {
      const c = COORDS[code];
      return {
        key: code,
        name: REGION_LABELS[code] ?? code,
        area: c.area,
        flag: REGION_COUNTRY[code] ?? "sg",
        lat: c.lat,
        lon: c.lon,
        ms: c.ms,
        nodeIds,
      };
    })
    .sort((a, b) => a.key.localeCompare(b.key));
}

/* Country codes broadly in Europe — the same grouping already implicit in
   lib/geo-currency.ts's Eurozone/non-euro-Europe sections, kept as its own
   small set here because this is a LOCATION decision, not a currency one (a
   Swiss or Norwegian visitor isn't in the Eurozone but is exactly who the
   Falkenstein, DE node — `fsn1` — is closest to). */
const EUROPEAN_COUNTRY_CODES = new Set([
  "AT", "BE", "HR", "CY", "EE", "FI", "FR", "DE", "GR", "IE", "IT", "LV", "LT", "LU",
  "MT", "NL", "PT", "SK", "SI", "ES", "AD", "MC", "SM", "VA", "ME", "XK",
  "GB", "GI", "IM", "JE", "GG", "CH", "LI", "SE", "NO", "DK", "IS", "FO", "GL",
  "PL", "CZ", "HU", "RO", "BG", "RS", "MK", "AL", "BA", "MD", "UA", "RU", "BY",
]);

/**
 * Which region a FRESH order should start on.
 *
 * Real signal first: if the visitor is in Europe and the platform has a
 * Europe-area node (Falkenstein, live since 2026-09-14), start there — that's
 * the entire point of running a second region, not just a nicer-looking
 * label. Otherwise a FIXED, deterministic default: Singapore (`sgp1`), the
 * platform's original/primary node, chosen because it's the platform's real
 * primary location — never "whichever region a `Node` query happened to
 * return first," which is how a customer could previously land on a random
 * datacentre with no region actually chosen (app/dashboard/deploy/page.tsx).
 * Falls back to the first region in the alphabetically-stable list above if
 * even Singapore isn't offered (e.g. on a differently-configured environment).
 */
export function defaultRegionKey(regions: Region[], visitorCountry: string | null): string | null {
  if (!regions.length) return null;
  if (visitorCountry) {
    const cc = visitorCountry.trim().toUpperCase();
    if (EUROPEAN_COUNTRY_CODES.has(cc)) {
      const eu = regions.find((r) => r.area === "Europe");
      if (eu) return eu.key;
    }
  }
  return regions.find((r) => r.key === "sgp1")?.key ?? regions[0].key;
}

