/* ── 16px minimum on every text input, on phones ─────────────────────────
 * iOS Safari force-zooms the page on focus of any text field rendered
 * smaller than 16px — there is no way to opt out of that browser behaviour
 * from the page itself, only avoid triggering it. The deploy wizard's `.field`
 * inputs (components/nx/DeployView.tsx, OrderBits.tsx) and the shared `.input`
 * class (/register, /login, /contact — components/AuthForms.tsx and friends)
 * were mostly 12.5–14px, tuned for the desktop design. Every one of those is a
 * Tailwind utility class living in Tailwind's own `utilities` @layer; this
 * rule is deliberately left UNLAYERED (not wrapped in any `@layer` block —
 * see the `:root:has(.nx-shell-root)` scoping note above for the same
 * convention elsewhere in this file), which under the CSS Cascade Layers spec
 * always outranks anything inside a layer regardless of selector specificity
 * or source order — so this one rule overrides every current (and future)
 * `text-[Npx]` utility on an input/select/textarea below the phone breakpoint
 * without having to hunt down and edit each one individually. Desktop keeps
 * the tighter, tuned type scale untouched. */
@media (max-width: 640px) {
  input, select, textarea { font-size: 16px; }
}

