/* MarketingHeader (components/marketing/MarketingHeader.tsx) is ALSO
 * `position: sticky; top: 0`, at a fixed `h-[72px]` on every breakpoint —
 * unlike the dashboard's Shell topbar, marketing's header height never
 * varies. Both this bar and that header being independently stuck at the
 * same `top: 0` meant that, the moment a visitor scrolled, they occupied the
 * exact same viewport slot: this bar's z-index (55) is higher than the
 * header's (50), so it painted OVER the header — and everything stacked
 * inside the header's own box (the products mega-menu, the mobile drawer,
 * the Log in / Get started CTAs in both) inherits that same lower ceiling,
 * so those got hidden behind the bar too, not just the header's own bar of
 * links. Pinning this bar `72px` down instead of `0`, and BELOW the header's
 * z-index rather than above it, makes them stack correctly — header on top,
 * bar directly beneath it — instead of overlapping. Scoped to
 * `.marketing-promo-stack` (app/(marketing)/layout.tsx, app/page.tsx) rather
 * than changing `.promo-bar` itself, which the dashboard also uses above a
 * differently-sized topbar (see the note on `.promo-bar` above).
 */
.marketing-promo-stack .promo-bar {
  top: 72px;
  z-index: 45;
}

