    {
    icon: <IconChat />,
    title: "Response time",
    // Quoted from lib/support-promise.ts, not retyped: four surfaces used to
    // carry four different reply times and this was the honest one.
    body: `We reply to every message ${SUPPORT_REPLY_WITHIN}.`,
    detail: `~1 ${SUPPORT_REPLY_WINDOW}`,
  },
];

