import { chromium } from "playwright";
import fs from "node:fs";

const BASE = "http://localhost:3002";
const OUT = "/tmp/claude-0/-root/ec6fa978-d80b-4147-9982-eea470598e2c/scratchpad/shots";
fs.mkdirSync(OUT, { recursive: true });

const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 });
const page = await ctx.newPage();

async function shot(name) {
  await page.screenshot({ path: `${OUT}/${name}.png` });
  console.log("saved", name);
}

// 1. Homepage first-visit: cookie banner + header CTA + promo bar/header stacking
await page.goto(`${BASE}/`, { waitUntil: "networkidle" });
await page.waitForTimeout(1500);
await shot("01-home-first-visit-cookiebanner");

// Scroll down to trigger sticky header + promo bar (if any) stacking
await page.evaluate(() => window.scrollTo(0, 600));
await page.waitForTimeout(500);
await shot("02-home-scrolled-header-stack");

// Dismiss cookie banner to see header CTA clearly
const gotIt = page.getByRole("button", { name: "Got it" });
if (await gotIt.count()) {
  await gotIt.click();
  await page.waitForTimeout(300);
}
await page.evaluate(() => window.scrollTo(0, 0));
await shot("03-home-header-mobile-cta");

// 2. Contact page: input font sizes (zoom check is about computed font-size, capture DOM value)
await page.goto(`${BASE}/contact`, { waitUntil: "networkidle" });
await page.waitForTimeout(500);
const nameInput = page.locator("#cf-name");
if (await nameInput.count()) {
  const fs1 = await nameInput.evaluate((el) => getComputedStyle(el).fontSize);
  console.log("contact #cf-name computed font-size:", fs1);
}
await shot("04-contact-mobile");

await browser.close();

