import { chromium } from "playwright";

const BASE = "http://localhost:3002";
const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 390, height: 844 } });
const page = await ctx.newPage();
await page.goto(`${BASE}/`, { waitUntil: "networkidle" });
await page.waitForTimeout(1200);
const closeBtn = page.locator("button[aria-label='Close']");
if (await closeBtn.count()) { await closeBtn.click(); await page.waitForTimeout(400); }

const info = await page.evaluate(() => {
  const bar = document.querySelector(".promo-bar");
  if (!bar) return { found: false };
  const cs = getComputedStyle(bar);
  const wrapper = bar.closest(".marketing-promo-stack");
  return {
    found: true,
    position: cs.position,
    top: cs.top,
    zIndex: cs.zIndex,
    hasWrapperAncestor: !!wrapper,
    wrapperClass: wrapper ? wrapper.className : null,
    barParentChain: (() => {
      let el = bar, chain = [];
      for (let i = 0; i < 5 && el; i++) { chain.push(el.tagName + "." + el.className); el = el.parentElement; }
      return chain;
    })(),
  };
});
console.log(JSON.stringify(info, null, 2));
await browser.close();

