import { chromium } from "playwright";
import fs from "node:fs";
import { execSync } from "node:child_process";

const BASE = "http://localhost:3002";
const OUT = "/tmp/claude-0/-root/ec6fa978-d80b-4147-9982-eea470598e2c/scratchpad/shots";
fs.mkdirSync(OUT, { recursive: true });
const DB = "postgresql://nxeon_staging:601ff5eee2d05c7af30b3c2df45431c1337a184b1ab65e43@localhost:5432/nxeon_staging";

const EMAIL = `mobiletest${Date.now()}@nxeon.local`;
const PASSWORD = "Testing12345!";

const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 });
const page = await ctx.newPage();

async function shot(name) {
  await page.screenshot({ path: `${OUT}/${name}.png` });
  console.log("saved", name);
}

// Register
await page.goto(`${BASE}/register`, { waitUntil: "networkidle" });
const gotIt = page.getByRole("button", { name: "Got it" });
if (await gotIt.count()) await gotIt.click();
await page.fill("#register-name", "Mobile Test");
await page.fill("#register-email", EMAIL);
await page.locator('input[type="password"]').first().fill(PASSWORD);
await page.getByRole("button", { name: "Create account" }).click();
for (let i = 0; i < 15 && !page.url().includes("/dashboard"); i++) await page.waitForTimeout(1000);
console.log("registered, at", page.url());

// Verify email + skip the "how did you hear about us" onboarding prompt directly in DB
execSync(`psql "${DB}" -c "UPDATE \\"User\\" SET \\"emailVerifiedAt\\" = now() WHERE email = '${EMAIL}';"`, { stdio: "inherit" });

// Reload dashboard so the verified state takes effect
await page.goto(`${BASE}/dashboard/deploy`, { waitUntil: "networkidle" });
await page.waitForTimeout(1000);
const gotIt2 = page.getByRole("button", { name: "Got it" });
if (await gotIt2.count()) await gotIt2.click();
await page.waitForTimeout(300);
await shot("20-wizard-step0-service");

// STEP 1: pick VPS service
await page.getByText("VPS Servers", { exact: false }).first().click();
await page.waitForTimeout(600);
await shot("21-wizard-step-configure-plan");

// Confirm current step index via the step marks (aria-current="step")
async function currentStepLabel() {
  return page.evaluate(() => {
    const cur = document.querySelector('[aria-current="step"]');
    return cur ? cur.textContent : null;
  });
}
console.log("step after picking VPS:", await currentStepLabel());

// pick a plan tile -> should auto-advance to region
const planCards = page.locator(".card, [class*=plan]").filter({ hasText: "GB" });
// Fall back: click first "Pick"-like element with a $ price - just click first plan card by test of button role
const anyPlanButton = page.locator("button, [role=button]").filter({ hasText: "/mo" }).first();
if (await anyPlanButton.count()) {
  await anyPlanButton.click();
  await page.waitForTimeout(500);
}
console.log("step after picking plan:", await currentStepLabel());
await shot("22-wizard-after-plan-pick");

// Try RE-clicking "VPS Servers" tile again by going back to step 0 via the step rail,
// to test the chooseService idempotency fix (should NOT wipe plan/term selections)
// Navigate back using the step rail's first step
const firstStepBtn = page.locator("ol li button").first();
await firstStepBtn.click();
await page.waitForTimeout(400);
await shot("23-wizard-back-to-service-step");

// Record current order state via a hidden probe: check the VPS tile is marked selected (on),
// then re-click it
const vpsTile = page.getByText("VPS Servers", { exact: false }).first();
await vpsTile.click();
await page.waitForTimeout(500);
await shot("24-wizard-reclicked-vps-tile");

await browser.close();
console.log("EMAIL_USED", EMAIL);

