// Capture the bottom bar's summary (plan name + term) BEFORE re-selecting the tile
async function bottomBarSummary() {
  return page.evaluate(() => {
    const bars = document.querySelectorAll(".nx-dark-island");
    const bottom = bars[bars.length - 1];
    return bottom ? bottom.textContent.replace(/\s+/g, " ").trim() : null;
  });
}
const summaryBefore = await bottomBarSummary();
console.log("SUMMARY BEFORE re-click:", summaryBefore);

// Try RE-clicking "VPS Servers" tile again by going back to step 0 via the step rail,
// to test the chooseService idempotency fix (should NOT wipe plan/term selections)
const firstStepBtn = page.locator("ol li button").first();
