await page.waitForTimeout(400);
await shot("23-wizard-back-to-service-step");

const vpsTile = page.getByText("VPS Servers", { exact: false }).first();
await vpsTile.click();
await page.waitForTimeout(500);
const summaryAfter = await bottomBarSummary();
console.log("SUMMARY AFTER re-click:", summaryAfter);
console.log("STATE PRESERVED:", summaryBefore === summaryAfter);

