const DB = "postgresql://nxeon_staging:601ff5eee2d05c7af30b3c2df45431c1337a184b1ab65e43@localhost:5432/nxeon_staging";
const EMAIL = `mobilepay${Date.now()}@nxeon.local`;
const PASSWORD = "Testing12345!";

const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 });
const page = await ctx.newPage();
page.setDefaultTimeout(12000);

async function shot(name) { await page.screenshot({ path: `${OUT}/${name}.png` }); console.log("saved", name); }
async function dismissOverlays() {
  for (let i = 0; i < 4; i++) {
    const closeBtn = page.locator("button[aria-label='Close']");
    if (await closeBtn.count()) { await closeBtn.first().click().catch(() => {}); await page.waitForTimeout(300); continue; }
    const skipHeard = page.getByRole("button", { name: "Skip" });
    if (await skipHeard.count()) { await skipHeard.first().click().catch(() => {}); await page.waitForTimeout(300); continue; }
    const gotIt2 = page.getByRole("button", { name: "Got it" });
    if (await gotIt2.count()) { await gotIt2.first().click().catch(() => {}); await page.waitForTimeout(300); continue; }
    break;
  }
}

await page.goto(`${BASE}/register`, { waitUntil: "domcontentloaded" });
await page.waitForTimeout(800);
await dismissOverlays();
await page.fill("#register-name", "Mobile Pay");
await page.fill("#register-email", EMAIL);
await page.locator('input[type="password"]').first().fill(PASSWORD);
await page.getByRole("button", { name: "Create account" }).click();
for (let i = 0; i < 15 && !page.url().includes("/dashboard"); i++) await page.waitForTimeout(1000);

execSync(`psql "${DB}" -c "UPDATE \\"User\\" SET \\"emailVerifiedAt\\" = now(), \\"heardAboutUs\\" = 'other' WHERE email = '${EMAIL}';"`, { stdio: "inherit" });

await page.goto(`${BASE}/dashboard/deploy`, { waitUntil: "domcontentloaded" });
await page.waitForTimeout(2000);
await dismissOverlays();
await page.waitForTimeout(500);
await dismissOverlays();

await page.getByText("VPS Servers", { exact: false }).first().click();
await page.waitForTimeout(600);
await dismissOverlays();

const selectPlanButtons = page.getByRole("button", { name: "Select plan" });
await selectPlanButtons.first().scrollIntoViewIfNeeded();
await selectPlanButtons.first().click();
await page.waitForTimeout(600);
await shot("30-region-step");

// Region step: click Next (region has a default already)
const nextBtn = page.getByRole("button", { name: /^Next/ });
if (await nextBtn.count()) { await nextBtn.first().click(); await page.waitForTimeout(700); }
await shot("31-after-region-next");

// Might land on payment step now. Check the step label + bottom bar text.
const stepInfo = await page.evaluate(() => {
  const cur = document.querySelector('[aria-current="step"]');
  return cur ? cur.textContent : null;
});
console.log("current step:", stepInfo);

// Scroll to bottom to see the fixed bottom bar & any mobile hint
await shot("32-payment-step-top");
const bottomBarText = await page.evaluate(() => {
  const islands = document.querySelectorAll(".nx-dark-island");
  return Array.from(islands).map((el) => el.textContent.replace(/\s+/g, " ").trim());
});
console.log("islands:", JSON.stringify(bottomBarText, null, 2));

// scroll main content to reveal "Card details are above." copy + bottom bar button label
await page.evaluate(() => window.scrollTo(0, 600));
await page.waitForTimeout(400);
await shot("33-payment-step-scrolled");

const cardCopy = await page.evaluate(() => {
  const el = Array.from(document.querySelectorAll("span")).find((s) => s.textContent.includes("Card details"));
  return el ? el.parentElement.textContent : null;
});
console.log("card copy:", cardCopy);

await browser.close();
console.log("DONE", EMAIL);

